WITH with_windows AS (SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY order_id), 4) AS amount_share, NTILE(10) OVER (PARTITION BY order_id ORDER BY amount DESC, id) AS amount_bucket, FIRST_VALUE(method) IGNORE NULLS OVER w_hist AS first_known_method FROM payments WINDOW w_hist AS (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, status, amount_bucket FROM with_windows ORDER BY id DESC;
